use vstd::prelude::*;

verus! {
    /// Remove the k-th element (1-based) from `list`, returning a new vector one element shorter.
    /// Requires 1 ≤ k < list.len().
    fn remove_kth_element(list: &Vec<i32>, k: usize) -> (result: Vec<i32>)
        requires
            1 <= k,
            k < list.len(),
        ensures
            result.len() == list.len() - 1,
        ensures
            // All elements before the removed index stay the same
            forall |i: usize|
                i < k - 1
                implies result[i] == list[i],
        ensures
            // All elements at or after the removed index are shifted by one
            forall |i: usize|
                (k - 1) <= i && i < result.len()
                implies result[i] == list[i + 1],
    {
        let n = list.len();
        let remove_idx = k - 1; // convert to 0-based index

        // Prepare a new vector with one fewer element
        let mut new_list = Vec::with_capacity(n - 1);
        
        // Take all elements before the removal index
        new_list.extend_from_slice(&list[..remove_idx]);
        // Take all elements after the removal index
        new_list.extend_from_slice(&list[remove_idx + 1..]);
        
        new_list
    }
}

